// PivirtdServiceServer is the server API for PivirtdService service.
// All implementations must embed UnimplementedPivirtdServiceServer
// for forward compatibility.
//
// Main Pivirtd Service - Replacement for libvirtd
type PivirtdServiceServer interface {
	// VM Lifecycle Management
	CreateVM(context.Context, *CreateVMRequest) (*VMResponse, error)
	StartVM(context.Context, *StartVMRequest) (*VMResponse, error)
	StopVM(context.Context, *StopVMRequest) (*VMResponse, error)
	PauseVM(context.Context, *PauseVMRequest) (*VMResponse, error)
	ResumeVM(context.Context, *ResumeVMRequest) (*VMResponse, error)
	RebootVM(context.Context, *RebootVMRequest) (*VMResponse, error)
	DeleteVM(context.Context, *DeleteVMRequest) (*DeleteVMResponse, error)
	// VM Queries
	ListVMs(context.Context, *ListVMsRequest) (*ListVMsResponse, error)
	GetVM(context.Context, *GetVMRequest) (*VMResponse, error)
	GetVMStats(context.Context, *GetVMStatsRequest) (*VMStatsResponse, error)
	UpdateVMMemory(context.Context, *UpdateVMMemoryRequest) (*VMResponse, error)
	UpdateVMCpu(context.Context, *UpdateVMCpuRequest) (*VMResponse, error)
	// QMP Passthrough
	ExecuteQMP(context.Context, *ExecuteQMPRequest) (*ExecuteQMPResponse, error)
	StreamQMPEvents(*StreamQMPRequest, grpc.ServerStreamingServer[QMPEvent]) error
	// Snapshot Management
	CreateSnapshot(context.Context, *CreateSnapshotRequest) (*SnapshotResponse, error)
	ListSnapshots(context.Context, *ListSnapshotsRequest) (*ListSnapshotsResponse, error)
	RestoreSnapshot(context.Context, *RestoreSnapshotRequest) (*SnapshotResponse, error)
	DeleteSnapshot(context.Context, *DeleteSnapshotRequest) (*DeleteSnapshotResponse, error)
	ConsolidateSnapshot(context.Context, *ConsolidateSnapshotRequest) (*SnapshotResponse, error)
	GetSnapshotStatus(context.Context, *GetSnapshotStatusRequest) (*SnapshotStatusResponse, error)
	// Clone Operations
	CloneVM(context.Context, *CloneVMRequest) (*VMResponse, error)
	CloneSnapshot(context.Context, *CloneSnapshotRequest) (*VMResponse, error)
	// Migration
	MigrateVM(context.Context, *MigrateVMRequest) (*MigrateVMResponse, error)
	GetMigrationStatus(context.Context, *GetMigrationStatusRequest) (*MigrationStatusResponse, error)
	// Storage Management
	CreateStoragePool(context.Context, *CreateStoragePoolRequest) (*StoragePoolResponse, error)
	ListStoragePools(context.Context, *ListStoragePoolsRequest) (*ListStoragePoolsResponse, error)
	DeleteStoragePool(context.Context, *DeleteStoragePoolRequest) (*DeleteStoragePoolResponse, error)
	// Network Management
	CreateTAPDevice(context.Context, *CreateTAPDeviceRequest) (*NetworkResponse, error)
	DeleteTAPDevice(context.Context, *DeleteTAPDeviceRequest) (*DeleteNetworkResponse, error)
	ListTAPDevices(context.Context, *ListTAPDevicesRequest) (*ListTAPDevicesResponse, error)
	CreateBridge(context.Context, *CreateBridgeRequest) (*NetworkResponse, error)
	DeleteBridge(context.Context, *DeleteBridgeRequest) (*DeleteNetworkResponse, error)
	ListBridges(context.Context, *ListBridgesRequest) (*ListBridgesResponse, error)
	// OVS Networking
	CreateOVSBridge(context.Context, *CreateOVSBridgeRequest) (*NetworkResponse, error)
	DeleteOVSBridge(context.Context, *DeleteOVSBridgeRequest) (*DeleteNetworkResponse, error)
	ListOVSBridges(context.Context, *ListOVSBridgesRequest) (*ListOVSBridgesResponse, error)
	AddOVSPort(context.Context, *AddOVSPortRequest) (*NetworkResponse, error)
	RemoveOVSPort(context.Context, *RemoveOVSPortRequest) (*DeleteNetworkResponse, error)
	ListOVSPorts(context.Context, *ListOVSPortsRequest) (*ListOVSPortsResponse, error)
	// VM Metadata Labels
	SetLabels(context.Context, *SetLabelsRequest) (*SetLabelsResponse, error)
	GetLabels(context.Context, *GetLabelsRequest) (*GetLabelsResponse, error)
	// VM Provisioning
	SetProvisioning(context.Context, *SetProvisioningRequest) (*SetProvisioningResponse, error)
	// VM Status
	GetVMStatus(context.Context, *GetVMStatusRequest) (*GetVMStatusResponse, error)
	// Disk Move (live block job mirroring)
	StartDiskMove(context.Context, *StartDiskMoveRequest) (*DiskMoveStatusResponse, error)
	GetDiskMoveStatus(context.Context, *GetDiskMoveStatusRequest) (*DiskMoveStatusResponse, error)
	CancelDiskMove(context.Context, *CancelDiskMoveRequest) (*DiskMoveResponse, error)
	// VM Device Hot-plug
	AttachDisk(context.Context, *AttachDiskRequest) (*VMResponse, error)
	DetachDisk(context.Context, *DetachDiskRequest) (*VMResponse, error)
	AttachNIC(context.Context, *AttachNICRequest) (*VMResponse, error)
	DetachNIC(context.Context, *DetachNICRequest) (*VMResponse, error)
	// Live Reconfiguration
	ResizeDisk(context.Context, *ResizeDiskRequest) (*VMResponse, error)
	SetVNCPassword(context.Context, *SetVNCPasswordRequest) (*VMResponse, error)
	SetLinkState(context.Context, *SetLinkStateRequest) (*VMResponse, error)
	// Snapshot Tree
	GetSnapshotTree(context.Context, *GetSnapshotTreeRequest) (*GetSnapshotTreeResponse, error)
	// Guest Agent
	GetGuestInfo(context.Context, *GetGuestInfoRequest) (*GetGuestInfoResponse, error)
	GuestExec(context.Context, *GuestExecRequest) (*GuestExecResponse, error)
	GetGuestExecStatus(context.Context, *GetGuestExecStatusRequest) (*GetGuestExecStatusResponse, error)
	SetGuestHostname(context.Context, *SetGuestHostnameRequest) (*SetGuestHostnameResponse, error)
	CustomizeOS(context.Context, *CustomizeOSRequest) (*CustomizeOSResponse, error)
	// Event Streaming
	SubscribeEvents(*SubscribeEventsRequest, grpc.ServerStreamingServer[HostEvent]) error
	GetHostResource(context.Context, *SubscribeEventsRequest) (*HostResourceReport, error)
	mustEmbedUnimplementedPivirtdServiceServer()
}

